def find_browser():
    candidates = [
        "chromium-browser",
        "chromium",
        "google-chrome",
        "google-chrome-stable",
        "/data/data/com.termux/files/usr/bin/chromium-browser",
        "/data/data/com.termux/files/usr/bin/chromium",
        "/data/data/com.termux/files/usr/bin/google-chrome"
    ]
    for c in candidates:
        p = shutil.which(c)
        if p:
            return p
    return None

def make_ws_frame(msg):
    data = msg.encode('utf-8')
    length = len(data)
    frame = bytearray([0x81])
    mask = os.urandom(4)
    if length <= 125: frame.append(0x80 | length)
    elif length <= 65535: frame.append(0x80 | 126); frame.extend(struct.pack('>H', length))
    else: frame.append(0x80 | 127); frame.extend(struct.pack('>Q', length))
    frame.extend(mask)
    frame.extend(bytearray(b ^ mask[i % 4] for i, b in enumerate(data)))
    return bytes(frame)

def parse_ws_frame(s):
    h = s.recv(2)
    if not h: return None
    b1, b2 = h[0], h[1]
    masked = bool(b2 & 0x80)
    length = b2 & 0x7F
    if length == 126: length = struct.unpack('>H', s.recv(2))[0]
    elif length == 127: length = struct.unpack('>Q', s.recv(8))[0]
    if masked: mask = s.recv(4)
    data = b''
    while len(data) < length:
        chunk = s.recv(length - len(data))
        if not chunk: break
        data += chunk
    if masked: data = bytes(b ^ mask[i % 4] for i, b in enumerate(data))
    return data.decode('utf-8', errors='ignore')

def ws_connect(port, ws_url):
    ws_path = "/" + ws_url.split("/", 3)[3]
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.connect(("127.0.0.1", port))
    req = f"GET {ws_path} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\n\r\n"
    s.sendall(req.encode('utf-8'))
    s.recv(4096)
    return s

def ws_eval(s, expr, req_id):
    payload = {"id": req_id, "method": "Runtime.evaluate", "params": {"expression": expr, "awaitPromise": True, "returnByValue": True}}
    s.sendall(make_ws_frame(json.dumps(payload)))
    while True:
        msg = parse_ws_frame(s)
        if not msg: continue
        res = json.loads(msg)
        if res.get("id") == req_id:
            return res.get("result", {}).get("result", {}).get("value")

